const http = require('http');
const fs = require('fs');
const path = require('path');

const endpoint = new URL('http://127.0.0.1:63699/status');

const req = http.get(endpoint, (res) => {
  const status = res.statusCode;
  const outDir = path.join(__dirname, 'results');
  if (!fs.existsSync(outDir)) {
    fs.mkdirSync(outDir, { recursive: true });
  }
  const outPath = path.join(outDir, 'status.json');
  fs.writeFileSync(outPath, JSON.stringify({ status }));
  console.log(`status=${status} written to ${outPath}`);
  res.resume();
});

req.on('error', (err) => {
  console.error(`Request failed: ${err.message}`);
  process.exit(1);
});

